let attempt=null, timerHandle=null, noticeHandle=null, storageAvailable=true, hasWarned=false, openCombo=null;
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).toLocaleLowerCase('fr').replaceAll('’',"'");
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"></use></svg>`;
function trOriginal(text){return String(text).split(/([\p{L}]+(?:[’'\-][\p{L}]+)*)/u).map((part,i)=>{if(i%2===0)return esc(part);const ar=GLOSSARY[norm(part)];return ar?`<span class="term" data-ar="${esc(ar)}">${esc(part)}</span>`:esc(part)}).join('')}
const tx=(text,cls='')=>`<span class="translate ${cls}">${tr(text)}</span>`;
function brand(){return `<div class="brand"><span class="brand-mark">${icon('lab')}</span><div>LAB <span style="font-weight:450">2AC</span><small>INFORMATIQUE AU COLLÈGE</small></div></div>`}
function readAttemptOriginal(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return null;const a=JSON.parse(raw);if(a.version!==1||!a.identity||typeof a.startedAt!=='number'||typeof a.deadline!=='number'||a.deadline-a.startedAt!==DURATION||!a.answers||typeof a.answers!=='object'||!['active','submitted'].includes(a.status))return null;return a}catch(e){storageAvailable=false;return null}}
function saveAttemptOriginal(){if(!attempt)return;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(attempt));storageAvailable=true}catch(e){storageAvailable=false}const el=$('#save-label');if(el)el.textContent=storageAvailable?'Réponses enregistrées sur cet appareil':'Sauvegarde indisponible : garde la page ouverte';}
function answered(id){return String(attempt?.answers?.[id]??'').trim().length>0}
function complete(q){return GROUPS[q].every(answered)}
function completedCount(){return Object.keys(GROUPS).filter(complete).length}
function formatTime(ms){const n=Math.max(0,Math.ceil(ms/1000));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function localDate(value){return new Intl.DateTimeFormat('fr-MA',{dateStyle:'short',timeStyle:'medium',timeZone:'Africa/Casablanca'}).format(new Date(value))}
function renderLoginOriginal(){clearInterval(timerHandle);hideTooltip();const saved=attempt;$('#app').innerHTML=`<div id="login-view"><header class="topbar">${brand()}<span class="session-tag">ÉVALUATION 01 · 2AC</span></header><main class="login-layout"><section class="intro"><div class="eyebrow">${icon('lab')} ${tx('SÉANCES 1 ET 2')}</div><h1>${tx('Information')}<br><em>& ${tx('matériel')}.</em></h1><p>${tx('Une évaluation pour mobiliser ce que tu as appris en informatique. Observe, réfléchis et choisis avec soin.')}</p><div class="quick-stats"><div class="quick-stat"><strong>20 min</strong><span>${tx('Temps disponible')}</span></div><div class="quick-stat"><strong>20 pts</strong><span>${tx('Note maximale')}</span></div><div class="quick-stat"><strong>4</strong><span>${tx('Parties à explorer')}</span></div></div><div class="intro-photo"><img src="${ASSETS.keyboard}" alt="Un aperçu du matériel observé pendant l’évaluation"><span class="photo-corner">OBSERVER · COMPRENDRE · APPLIQUER</span></div><p class="bottom-note">${icon('check')}${tx('Travail individuel. Réponses en français.')}</p></section><section class="login-card" aria-labelledby="login-title"><span class="form-step"><i>01</i>${tx('AVANT DE COMMENCER')}</span><h2 id="login-title">${tx('Identifie ta copie.')}</h2><p class="lead">${tx('Indique ton nom, ta classe et ton groupe. Le compte à rebours commence quand tu entres dans l’examen.')}</p>${saved?`<div class="resume-card"><strong>${tx(saved.status==='submitted'?'Une copie a déjà été rendue.':'Une session est déjà en cours.')}</strong><p>${esc(saved.identity.name)} · ${esc(saved.identity.className)} · Groupe ${esc(saved.identity.group)}${saved.status==='active'?`<br>${tx('Temps restant')} : <b>${formatTime(saved.deadline-Date.now())}</b>`:''}</p><button type="button" class="button-primary" id="resume-attempt">${tx(saved.status==='submitted'?'Voir ma copie':'Reprendre mon examen')} ${icon('arrow')}</button></div>`:`<form id="identity-form" novalidate><div class="field"><label for="student-name">${tx('Nom complet')}</label><input id="student-name" name="name" type="text" dir="auto" autocomplete="name" placeholder="Prénom et nom" maxlength="100" required aria-describedby="name-error"><div class="form-error" id="name-error" role="alert" hidden></div></div><div class="field-pair"><div class="field"><label id="class-label">${tx('Classe')}</label>${combo('identity_class',Array.from({length:9},(_,i)=>`2/${i+1}`),'Ta classe',true)}</div><div class="field"><label id="group-label">${tx('Groupe')}</label>${combo('identity_group',['1','2'],'Ton groupe',true)}</div></div><div class="form-error" id="identity-error" role="alert" hidden></div><button class="start-button" type="submit">${tx('Commencer mes 20 minutes')} ${icon('arrow')}</button><p class="micro-note">${tx('Le chronomètre reste actif si tu recharges la page.')}</p></form>`}<div class="login-help">${icon('globe')}<div>${tx('Un mot difficile ? Survole-le pour afficher sa traduction arabe.')}<br><span class="hover-example" tabindex="0" data-ar="المعلومة">information</span> · ${tx('Déplace la souris pour masquer l’infobulle.')}</div></div>${!storageAvailable?`<p class="storage-alert">La sauvegarde locale est indisponible dans ce navigateur. Garde la page ouverte pendant l’examen.</p>`:''}</section></main><footer class="login-footer"><span>Abdellah TAHTOH · LAB 2AC</span><button type="button" class="button-plain" id="show-credits" style="font-size:10px;padding:0">Crédits des images et polices</button></footer></div>`;if(!saved){identityChoices={};$('#identity-form').addEventListener('submit',startAttempt)}}
let identityChoices={};
function combo(id,options,label,identity=false){const value=identity?(identityChoices[id]||''):(attempt?.answers[id]||'');return `<div class="combo" data-combo="${id}" ${identity?'data-identity="true"':''}><button type="button" class="combo-trigger ${!value?'empty':''}" id="combo-${id}" aria-haspopup="listbox" aria-expanded="false" aria-controls="list-${id}" aria-label="${esc(label)}"><span class="combo-value">${value?tr(value):tr('Choisir')}</span>${icon('chevron')}</button><div class="combo-menu" id="list-${id}" role="listbox" aria-label="${esc(label)}" hidden>${options.map((o,i)=>`<button type="button" role="option" class="combo-option" data-value="${esc(o)}" aria-selected="${o===value?'true':'false'}" tabindex="-1" id="${id}-option-${i}">${tr(o)}</button>`).join('')}</div></div>`}
function setCombo(el,value){const id=el.dataset.combo;if(el.dataset.identity){identityChoices[id]=value}else{if(!attempt||attempt.status!=='active'||clockNow()>=attempt.deadline){tick();return}attempt.answers[id]=value;saveAttempt();updateProgress()}const btn=$('.combo-trigger',el);$('.combo-value',el).innerHTML=tr(value);btn.classList.remove('empty');$$('.combo-option',el).forEach(x=>x.setAttribute('aria-selected',String(x.dataset.value===value)));closeCombos();hideTooltip();btn.focus({preventScroll:true})}
function closeCombos(){if(openCombo){$('.combo-menu',openCombo).hidden=true;$('.combo-trigger',openCombo).setAttribute('aria-expanded','false');openCombo=null}}
function openCombobox(el,focusFirst=false){if(openCombo===el){closeCombos();return}closeCombos();openCombo=el;$('.combo-menu',el).hidden=false;$('.combo-trigger',el).setAttribute('aria-expanded','true');if(focusFirst){const selected=$('.combo-option[aria-selected="true"]',el)||$('.combo-option',el);selected.focus()}}
function startAttemptOriginal(e){e.preventDefault();const name=$('#student-name').value.trim().replace(/\s+/g,' ');const err=$('#name-error');err.hidden=true;$('#identity-error').hidden=true;$('#student-name').removeAttribute('aria-invalid');if(name.length<4||name.split(/\s+/u).length<2||!/[\p{L}]/u.test(name)){err.textContent='Écris ton prénom et ton nom complets.';err.hidden=false;$('#student-name').setAttribute('aria-invalid','true');$('#student-name').focus();return}if(!identityChoices.identity_class||!identityChoices.identity_group){$('#identity-error').textContent='Choisis ta classe et ton groupe avant de commencer.';$('#identity-error').hidden=false;return}const now=Date.now();attempt={version:1,id:('E1-'+now.toString(36)+'-'+(globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2))).slice(0,28),identity:{name,className:identityChoices.identity_class,group:identityChoices.identity_group},startedAt:now,deadline:now+DURATION,status:'active',section:0,answers:{},submittedAt:null,reason:null};hasWarned=false;closeCombos();saveAttempt();renderExam()}
function qcardOriginal(id,n,title,points,body){return `<article class="question-card" id="${id}" data-question="${id}"><div class="question-top"><span class="question-number">${String(n).padStart(2,'0')}</span><h2>${tx(title)}</h2><span class="points">${points} ${points===1?'point':'points'}</span></div>${body}</article>`}
function input(id,label,extra='',value=''){return `<input class="answer-input" type="text" data-answer="${id}" id="${id}" aria-label="${esc(label)}" value="${esc(attempt?.answers[id]??value)}" autocomplete="off" ${extra}>`}
function radio(id,options){return `<div class="radio-grid">${options.map(o=>`<label class="radio-option"><input type="radio" name="${id}" data-answer="${id}" value="${esc(o)}" ${attempt?.answers[id]===o?'checked':''}>${tx(o)}</label>`).join('')}</div>`}
function sectionContentOriginal(n){if(n===0){return qcard('q1',1,'Complète la définition de l’informatique.',1,`<p class="question-hint">${tx('Écris un mot dans chaque case.')}</p><div class="cloze">${tx('L’informatique est la science du traitement')} ${input('definition_automatic','Premier mot de la définition','maxlength="35" spellcheck="true"')} ${tx('des')} ${input('definition_information','Deuxième mot de la définition','maxlength="35" spellcheck="true"')}.</div>`)+qcard('q2',2,'Quelle forme d’information correspond à chaque exemple ?',2,`<div>${[['message','Un SMS écrit','form_sms'],['image','Une photo de classe','form_photo'],['sound','Une sonnerie de téléphone','form_ring'],['video','Un clip filmé de la sortie scolaire','form_video']].map(([ic,label,id])=>`<div class="choice-row"><div class="row-example"><span class="example-icon">${icon(ic)}</span><div class="row-description">${tx(label)}</div></div>${combo(id,FORM_OPTIONS,label)}</div>`).join('')}</div>`)+qcard('q3',3,'Pour chaque situation, choisis le type de traitement.',3,`<div>${[['Un élève trie une liste de noms sur une feuille, à la main.','type_paper'],['Une caissière scanne chaque produit ; la caisse calcule le total.','type_checkout'],['Une sauvegarde programmée se lance toute seule chaque nuit.','type_backup']].map(([label,id])=>`<div class="choice-row"><div class="row-description">${tx(label)}</div>${combo(id,TYPE_OPTIONS,label)}</div>`).join('')}</div>`)+qcard('q4',4,'Quelle touche permet de valider une saisie ?',1,radio('validate_key',['Entrée','Échap','Retour arrière']));}
if(n===1){return qcard('q5',5,'Observe chaque appareil, puis indique son nom et sa catégorie.',4,`<p class="question-hint">${tx('Tu peux agrandir les photos. Chaque nom et chaque catégorie valent 0,5 point.')}</p><div class="material-grid">${[['a','keyboard'],['b','speakers'],['c','headset'],['d','usb']].map(([letter,img])=>`<div class="material-card"><div class="material-image"><span class="material-letter">${letter.toUpperCase()}</span><img data-material-photo="${img}" src="${ASSETS[img]}" alt="Matériel ${letter.toUpperCase()} à identifier"><button class="zoom-button" data-zoom="${img}" data-letter="${letter.toUpperCase()}" type="button" aria-label="Agrandir la photo ${letter.toUpperCase()}">${icon('zoom')}</button></div><div class="material-fields"><div><span class="field-label">${tx('Nom de l’appareil')}</span>${combo(`device_${letter}_name`,NAME_OPTIONS,`Nom du matériel ${letter.toUpperCase()}`)}</div><div><span class="field-label">${tx('Catégorie')}</span>${combo(`device_${letter}_category`,CATEGORY_OPTIONS,`Catégorie du matériel ${letter.toUpperCase()}`)}</div></div></div>`).join('')}</div>`);}
if(n===2){return qcard('q6',6,'Quel composant remplit chacun de ces rôles ?',2,`<p class="question-hint">${tx('Choisis le composant correspondant à chaque fonction.')}</p><div>${[['A','Conserve temporairement les données en cours d’utilisation.','component_ram'],['B','Exécute les instructions et réalise les calculs.','component_cpu'],['C','Fournit l’énergie électrique aux composants.','component_power'],['D','Relie les composants entre eux.','component_motherboard']].map(([l,t,id])=>`<div class="component-row"><span class="role-letter">${l}</span><span>${tx(t)}</span>${combo(id,COMPONENT_OPTIONS,`Composant pour le rôle ${l}`)}</div>`).join('')}</div>`)+qcard('q7',7,'Effectue les conversions de capacités.',3,`<p class="question-hint">${tx('Utilise la convention décimale étudiée en classe. Écris seulement le nombre demandé.')}</p><div class="conversion-grid">${[['conversion_bits','De l’octet au bit','1 octet =','bits'],['conversion_go_mo','Du Go au Mo','4 Go =','Mo'],['conversion_mo_go','Du Mo au Go','6 000 Mo =','Go']].map(([id,t,exp,unit])=>`<div class="conversion-box"><div class="conversion-label">${tx(t)}</div><div class="conversion-expression">${tx(exp)}</div><div class="conversion-answer">${input(id,`${exp} combien de ${unit}`,'inputmode="decimal" maxlength="14" placeholder="…"')}<span>${tx(unit)}</span></div></div>`).join('')}</div>`);}
return `<div class="situation"><span>${icon('video')}</span><div><div class="eyebrow">${tx('LA SITUATION')}</div><p>${tx('Le club prépare un reportage. Il veut enregistrer une voix, conserver le fichier après l’arrêt du PC, puis copier une vidéo de')} <b class="data-inline">${tx("2 500 Mo")}</b> ${tx('sur une clé USB qui dispose de')} <b class="data-inline">${tx("3 Go")}</b> ${tx('libres.')}</p></div></div>`+qcard('q8',8,'Quel périphérique permet d’enregistrer la voix ?',1,radio('voice_device',['Un microphone','Un haut-parleur','Un scanner']))+qcard('q9',9,'Un élève veut garder le fichier uniquement dans la RAM. Ce choix convient-il ?',2,`<p class="question-hint">${tx('Justifie ta réponse et nomme un composant interne adapté pour conserver le fichier après l’arrêt du PC.')}</p><textarea class="answer-area" id="ram_reason" data-answer="ram_reason" lang="fr" spellcheck="true" maxlength="600" aria-label="Justification du choix de stockage" placeholder="Réponds en français, en une ou deux phrases.">${esc(attempt?.answers.ram_reason??'')}</textarea><div class="answer-footnote"><span>${tx('Une explication courte et précise suffit.')}</span><span id="char-count">${String(attempt?.answers.ram_reason??'').length} / 600</span></div>`)+qcard('q10',10,'La clé dispose-t-elle d’assez d’espace pour copier la vidéo ?',1,`<p class="question-hint">${tx('Convertis d’abord l’espace libre en Mo, puis choisis ta conclusion.')}</p><div class="capacity-line">${tx("3 Go")} = ${input('available_mo','3 Go en Mo','inputmode="decimal" maxlength="14" placeholder="…"')} ${tx("Mo")}</div>${radio('video_fits',['Oui, l’espace suffit.','Non, l’espace est insuffisant.'])}`);}
function renderExamOriginal(){if(!attempt||attempt.status!=='active'){renderLogin();return}hideTooltip();closeCombos();const s=Math.max(0,Math.min(3,attempt.section||0));attempt.section=s;const initial=attempt.identity.name.split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase();$('#app').innerHTML=`<div id="exam-view"><header class="exam-header"><div class="header-left">${brand()}<div class="header-title">Évaluation 01<small>Séances 1 et 2 · 20 points</small></div></div><div class="header-actions"><div class="timer" id="exam-timer" role="timer" aria-label="Temps restant"><span class="timer-icon">${icon('clock')}</span><div><div class="timer-label">TEMPS RESTANT</div><div class="timer-value" id="time-value">${formatTime(attempt.deadline-clockNow())}</div></div></div><button class="button-primary" id="open-review" type="button">${tx('Rendre ma copie')} ${icon('check')}</button></div></header><div class="exam-layout"><aside class="sidebar" aria-label="Navigation de l’évaluation"><div class="identity"><div class="avatar">${esc(initial)}</div><div><div class="identity-name">${esc(attempt.identity.name)}</div><div class="identity-class">Classe ${esc(attempt.identity.className)} · Groupe ${esc(attempt.identity.group)}</div></div></div><div class="nav-heading">LES QUATRE PARTIES</div><nav class="part-nav">${SECTIONS.map((x,i)=>`<button type="button" class="part-button ${s===i?'active':''}" data-section="${i}" ${s===i?'aria-current="step"':''}><span class="part-number" data-part-number="${i}">${i+1}</span><span><strong>${tx(x.short)}</strong><small>${x.points} points · ${x.time} min conseillées</small></span></button>`).join('')}</nav><div class="progress-card"><strong id="progress-text"></strong><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="10" aria-valuenow="0" aria-label="Exercices complétés"><div class="progress-fill" id="progress-fill"></div></div><span class="muted">10 questions au total</span></div><div class="save-state">${icon('save')}<span id="save-label">Réponses enregistrées sur cet appareil</span></div><p class="sidebar-help">${tx('Survole une phrase pour lire sa traduction arabe.')}<br>${tx('Tu peux revenir aux parties précédentes.')}</p></aside><main class="exam-main" id="exam-main" tabindex="-1"><div class="mobile-identity">${esc(attempt.identity.name)} · Classe ${esc(attempt.identity.className)} · Groupe ${esc(attempt.identity.group)}</div>${SECTIONS.map((sec,i)=>`<section class="exam-section" data-exam-section="${i}" ${i!==s?'hidden':''} aria-labelledby="section-title-${i}"><div class="section-heading"><div><div class="eyebrow">PARTIE ${String(i+1).padStart(2,'0')} / 04</div><h1 id="section-title-${i}">${tx(sec.title)}</h1></div><span>${sec.points} points · ${sec.time} min conseillées</span></div><p class="section-description">${tx(sec.subtitle)}</p>${sectionContent(i)}</section>`).join('')}<footer class="section-footer"><button type="button" class="button-soft" id="previous-section" ${s===0?'disabled':''}>${icon('back')}${tx('Précédent')}</button><span class="section-step" id="section-step">Partie ${s+1} sur 4</span><button type="button" class="button-primary" id="next-section">${tx(s===3?'Vérifier ma copie':'Suivant')} ${icon('arrow')}</button></footer></main></div></div>`;updateProgress();if(!storageAvailable)$('#save-label').textContent='Sauvegarde indisponible : garde la page ouverte';clearInterval(timerHandle);tick();if(attempt.status==='active')timerHandle=setInterval(tick,250)}
function updateProgressOriginal(){if(!attempt)return;const n=completedCount();const p=$('#progress-text');if(p)p.textContent=`${n} / 10 questions complétées`;const bar=$('.progress-track');if(bar)bar.setAttribute('aria-valuenow',String(n));const fill=$('#progress-fill');if(fill)fill.style.width=`${n*10}%`;SECTIONS.forEach((s,i)=>{const done=s.questions.every(complete);const b=$(`[data-section="${i}"]`);if(b)b.classList.toggle('complete',done);const num=$(`[data-part-number="${i}"]`);if(num)num.innerHTML=done?icon('check'):String(i+1)})}
function goSection(n,q=null){if(!attempt||attempt.status!=='active')return;tick();if(attempt.status!=='active')return;closeCombos();hideTooltip();n=Math.min(3,Math.max(0,n));attempt.section=n;saveAttempt();$$('[data-exam-section]').forEach(el=>el.hidden=Number(el.dataset.examSection)!==n);$$('[data-section]').forEach(el=>{const active=Number(el.dataset.section)===n;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});$('#previous-section').disabled=n===0;$('#next-section').innerHTML=tx(n===3?'Vérifier ma copie':'Suivant')+' '+icon('arrow');$('#section-step').textContent=`Partie ${n+1} sur 4`;window.scrollTo({top:0,behavior:'instant'});if(q){requestAnimationFrame(()=>$('#'+q)?.scrollIntoView({block:'center',behavior:'smooth'}))}else $('#exam-main').focus({preventScroll:true})}
function tickOriginal(){if(!attempt||attempt.status!=='active')return;const left=attempt.deadline-clockNow();const v=$('#time-value');if(v)v.textContent=formatTime(left);const t=$('#exam-timer');if(t){t.classList.toggle('warning',left<=120000&&left>60000);t.classList.toggle('urgent',left<=60000);t.setAttribute('aria-label',`Temps restant ${formatTime(left)}`)}if(left<=120000&&left>0&&!hasWarned){hasWarned=true;showNotice('Il reste moins de 2 minutes. Pense à relire tes réponses.')}if(left<=0)submitAttempt('timeout')}
function showNotice(text){clearTimeout(noticeHandle);const n=$('#time-notice');n.textContent=text;n.hidden=false;noticeHandle=setTimeout(()=>n.hidden=true,8500)}
function openDialog(el){hideTooltip();closeCombos();el.showModal();document.body.classList.add('dialog-open')}
function closeDialog(el){el.close();if(!$$('dialog[open]').length)document.body.classList.remove('dialog-open');hideTooltip()}
function reviewOriginal(){if(!attempt||attempt.status!=='active')return;tick();if(attempt.status!=='active')return;const n=completedCount();$('#review-info').textContent=n===10?'Toutes les questions sont complétées. Prends un instant pour relire avant de rendre.':`${10-n} question${10-n>1?'s ne sont pas encore entièrement complétées.':' n’est pas encore entièrement complétée.'} Tu peux y revenir ou rendre ta copie en l’état.`;$('#review-count').textContent=`${n} / 10`;$('#review-list').innerHTML=Object.keys(GROUPS).map((q,i)=>`<button type="button" class="review-item ${complete(q)?'':'todo'}" data-review-question="${q}">${icon(complete(q)?'check':'paper')}<span>${i+1}. ${esc(QUESTION_TITLES[q])}</span></button>`).join('');openDialog($('#review-dialog'))}
function submitAttemptOriginal(reason){if(!attempt||attempt.status!=='active')return;const now=Date.now();if(reason==='manual'&&now>=attempt.deadline)reason='timeout';attempt.status='submitted';attempt.reason=reason;attempt.submittedAt=reason==='timeout'?attempt.deadline:now;attempt.durationSeconds=Math.min(1200,Math.max(0,Math.round((attempt.submittedAt-attempt.startedAt)/1000)));clearInterval(timerHandle);clearTimeout(noticeHandle);$('#time-notice').hidden=true;$$('dialog[open]').forEach(closeDialog);closeCombos();hideTooltip();saveAttempt();renderResult();window.scrollTo(0,0)}
function summaryBodyOriginal(){return Object.keys(GROUPS).map((q,i)=>`<div class="copy-question"><h3>${i+1}. ${esc(QUESTION_TITLES[q])}</h3>${GROUPS[q].map(id=>`<div class="copy-line"><span>${esc(LABELS[id].replace(/^Q\d+ · /,''))} :</span> ${answered(id)?`<b>${esc(attempt.answers[id]).replace(/\n/g,'<br>')}</b>`:'<b class="unanswered">Sans réponse</b>'}</div>`).join('')}</div>`).join('')}
function renderResultOriginal(){if(!attempt||attempt.status!=='submitted'){renderLogin();return}clearInterval(timerHandle);hideTooltip();const elapsed=attempt.durationSeconds??Math.min(1200,Math.round((attempt.submittedAt-attempt.startedAt)/1000));$('#app').innerHTML=`<div id="result-view"><header class="topbar">${brand()}<span class="session-tag">ÉVALUATION 01 · COPIE RENDUE</span></header><main class="result-main"><div class="result-hero"><div class="result-icon">${icon(attempt.reason==='timeout'?'clock':'check')}</div><div class="eyebrow">${tx('FIN DE L’ÉVALUATION')}</div><h1>${tx(attempt.reason==='timeout'?'Le temps est écoulé.':'Ta copie est prête.')}</h1><p>${tx(attempt.reason==='timeout'?'La confirmation ci-dessous indique si le professeur a bien reçu ta copie.':'La confirmation ci-dessous indique si le professeur a bien reçu ta copie.')}</p></div><section class="result-card"><div class="result-identity"><div><strong>${esc(attempt.identity.name)}</strong><small>Classe ${esc(attempt.identity.className)} · Groupe ${esc(attempt.identity.group)}</small></div><span class="result-status">${tx('Copie à corriger')}</span></div><div class="result-metrics"><div><span>${tx('Exercices complétés')}</span><strong>${completedCount()} / ${TOTAL_QUESTIONS}</strong></div><div><span>${tx('Temps utilisé')}</span><strong>${formatTime(elapsed*1000)}</strong></div><div><span>${tx('Fin de session')}</span><strong style="font-size:11px;line-height:1.7">${esc(localDate(attempt.submittedAt))}</strong></div></div></section><div class="delivery-anchor"></div><section class="result-card copy-summary"><details id="copy-details"><summary>${tx('Relire les réponses rendues')}</summary><div class="copy-body" id="copy-body">${summaryBody()}</div></details></section><div class="result-new"><button type="button" class="button-plain" id="new-student">${tx('Préparer une session pour le prochain élève')}</button></div></main></div>`}
function downloadBlob(content,type,extension){const safe=attempt.identity.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\p{L}\p{N}]+/gu,'_').slice(0,65);const filename=`Evaluation_1_${attempt.identity.className.replace('/','-')}_G${attempt.identity.group}_${safe}.${extension}`;const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function exportCopy(){if(attempt?.status!=='submitted')return;const html=`<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Copie · Évaluation 1 · ${esc(attempt.identity.name)}</title><style>body{font-family:Arial,sans-serif;color:#183c34;max-width:850px;margin:35px auto;padding:0 24px;line-height:1.8}h1{font-size:27px}h2{font-size:19px}h3{font-size:15px;border-bottom:1px solid #ddd;padding-bottom:5px}.meta{color:#52675d;font-size:13px}.copy-question{margin-top:25px;break-inside:avoid}.copy-line{font-size:14px;padding:4px 0;overflow-wrap:anywhere}.copy-line span{color:#566b60}.copy-line b{font-weight:600}.unanswered{color:#a15a1d}button{background:#163e34;color:#fff;border:0;padding:12px 20px;border-radius:8px;cursor:pointer}@media print{button{display:none}@page{size:A4;margin:16mm}body{margin:0;padding:0}}</style><h1>Évaluation 1 · Copie de l’élève</h1><h2>${esc(attempt.identity.name)}</h2><p class="meta">Classe ${esc(attempt.identity.className)} · Groupe ${esc(attempt.identity.group)}<br>Début : ${esc(localDate(attempt.startedAt))}<br>Fin : ${esc(localDate(attempt.submittedAt))}<br>Clôture : ${attempt.reason==='timeout'?'Temps écoulé':'Remise par l’élève'}<br>Questions entièrement complétées : ${completedCount()} / ${TOTAL_QUESTIONS}<br>Référence : ${esc(attempt.id)}</p><p>Copie à corriger · Note : ........ / 20</p><button onclick="window.print()">Imprimer cette copie</button>${summaryBody()}<hr><p class="meta">Abdellah TAHTOH · LAB 2AC · Heures affichées pour le Maroc.</p></html>`;downloadBlob(html,'text/html;charset=utf-8','html')}
function csvCell(v){let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function exportCSV(){if(attempt?.status!=='submitted')return;const meta=[attempt.id,attempt.identity.name,attempt.identity.className,attempt.identity.group,new Date(attempt.startedAt).toISOString(),new Date(attempt.submittedAt).toISOString(),attempt.durationSeconds,attempt.reason];const rows=[['Référence','Nom complet','Classe','Groupe','Début UTC','Fin UTC','Durée secondes','Clôture','Question','Réponse']];for(const id of Object.keys(LABELS))rows.push([...meta,LABELS[id],attempt.answers[id]||'']);downloadBlob('\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8','csv')}
let tooltipTarget=null;
function showTooltip(target){const content=target?.dataset.ar;if(!content)return;tooltipTarget=target;const tip=$('#word-tooltip');tip.textContent=content;tip.setAttribute('aria-hidden','false');target.setAttribute('aria-describedby','word-tooltip');tip.classList.add('visible');const r=target.getBoundingClientRect();const b=tip.getBoundingClientRect();let left=r.left+r.width/2-b.width/2;left=Math.max(10,Math.min(innerWidth-b.width-10,left));let top=r.top-b.height-10;if(top<8)top=r.bottom+10;tip.style.left=`${left}px`;tip.style.top=`${Math.max(8,Math.min(innerHeight-b.height-8,top))}px`}
function hideTooltip(){const tip=$('#word-tooltip');tip.classList.remove('visible');tip.setAttribute('aria-hidden','true');if(tooltipTarget)tooltipTarget.removeAttribute('aria-describedby');tooltipTarget=null}
document.addEventListener('pointerover',e=>{const t=e.target.closest('[data-ar]');if(t&&t!==tooltipTarget)showTooltip(t)});
document.addEventListener('pointerout',e=>{if(tooltipTarget&&!tooltipTarget.contains(e.relatedTarget))hideTooltip()});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-ar]'))showTooltip(e.target)});
document.addEventListener('focusout',hideTooltip);
document.addEventListener('pointercancel',hideTooltip);
document.addEventListener('scroll',hideTooltip,true);
document.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'){const t=e.target.closest('[data-ar]');if(t)showTooltip(t)}});
document.addEventListener('pointerup',e=>{if(e.pointerType==='touch')hideTooltip()});
window.addEventListener('blur',hideTooltip);
document.addEventListener('input',e=>{const el=e.target.closest('[data-answer]');if(!el)return;if(!attempt||attempt.status!=='active'||clockNow()>=attempt.deadline){tick();return}attempt.answers[el.dataset.answer]=el.value;saveAttempt();updateProgress();if(el.id==='ram_reason')$('#char-count').textContent=`${el.value.length} / 600`});
document.addEventListener('click',e=>{const target=e.target;const option=target.closest('.combo-option');if(option){setCombo(option.closest('.combo'),option.dataset.value);return}const trigger=target.closest('.combo-trigger');if(trigger){openCombobox(trigger.closest('.combo'));return}closeCombos();const section=target.closest('[data-section]');if(section){goSection(Number(section.dataset.section));return}const zoom=target.closest('[data-zoom]');if(zoom){$('#large-image').src=ASSETS[zoom.dataset.zoom];$('#large-image').alt=`Matériel ${zoom.dataset.letter} en grand format`;$('#image-title').textContent=`Matériel ${zoom.dataset.letter}`;openDialog($('#image-dialog'));return}if(target.closest('[data-close-dialog]')){closeDialog(target.closest('dialog'));return}const reviewQuestion=target.closest('[data-review-question]');if(reviewQuestion){closeDialog($('#review-dialog'));const q=reviewQuestion.dataset.reviewQuestion;goSection(SECTIONS.findIndex(s=>s.questions.includes(q)),q);return}const id=target.closest('button')?.id;switch(id){case 'resume-attempt':attempt.status==='submitted'?renderResult():renderExam();break;case 'previous-section':goSection(attempt.section-1);break;case 'next-section':attempt.section===3?review():goSection(attempt.section+1);break;case 'open-review':review();break;case 'confirm-submit':submitAttempt('manual');break;case 'download-copy':exportCopy();break;case 'export-csv':exportCSV();break;case 'print-copy':$('#copy-details').open=true;window.print();break;case 'new-student':openDialog($('#new-dialog'));break;case 'confirm-new':closeDialog($('#new-dialog'));try{localStorage.removeItem(STORAGE_KEY)}catch(err){}attempt=null;identityChoices={};renderLogin();window.scrollTo(0,0);break;case 'show-credits':openDialog($('#credits-dialog'));break}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideTooltip();const trigger=openCombo?$('.combo-trigger',openCombo):null;closeCombos();if(trigger)trigger.focus();return}const trigger=e.target.closest('.combo-trigger');if(trigger&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const c=trigger.closest('.combo');if(openCombo!==c)openCombobox(c);const opts=$$('.combo-option',c);(e.key==='End'||e.key==='ArrowUp'?opts.at(-1):opts[0]).focus();return}const op=e.target.closest('.combo-option');if(op&&['ArrowDown','ArrowUp','Home','End','Tab'].includes(e.key)){if(e.key==='Tab'){closeCombos();return}e.preventDefault();const opts=$$('.combo-option',op.closest('.combo'));let n=opts.indexOf(op);n=e.key==='Home'?0:e.key==='End'?opts.length-1:(n+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length;opts[n].focus()}});
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{hideTooltip();if(!$$('dialog[open]').length)document.body.classList.remove('dialog-open')});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})});
document.addEventListener('visibilitychange',()=>{hideTooltip();tick()});
window.addEventListener('pageshow',()=>{if(attempt?.status==='active')tick()});
window.addEventListener('beforeprint',()=>{const el=$('#copy-details');if(el)el.open=true});

// Adaptations de la page d’examen ; aucune réponse attendue n’est publiée ici.
const INTERNAL_OPTIONS=['Processeur','RAM','Carte mère','Disques de stockage','Alimentation','Carte graphique','Carte son','Carte Wi-Fi'];
const QUESTION_MAX={q1:1,q2:1,q3:3,q4:1,q5:3,q6:1,q6b:4,q7:2,q8:1,q9:2,q10:1};
const DISPLAY_NUMBER={q1:'01',q2:'02',q3:'03',q4:'04',q5:'05',q6:'06A',q6b:'06B',q7:'07',q8:'08',q9:'09',q10:'10'};
const TOTAL_QUESTIONS=Object.keys(GROUPS).length;
let serverOffset=0,lastSnapshot='',saveTimer=null,syncPromise=null,wantsSubmit=false,ackRevision=-1;
const stable=a=>JSON.stringify(Object.keys(a??{}).sort().map(k=>[k,String(a[k]).normalize('NFKC').trim()]).filter(([,v])=>v!==''));
function requestUUID(){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=[...b].map(x=>x.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20)}
function tr(text){const sentence=String(text);const arabic=PHRASES[sentence];return arabic?`<span class="phrase" data-ar="${esc(arabic)}" tabindex="0">${esc(sentence)}</span>`:esc(sentence)}
function clockNow(){return Date.now()+(attempt?.serverOffset??serverOffset)}
async function api(action,payload={},token=''){
 const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),18000);
 try{const response=await fetch(EVAL1_CONFIG.endpoint,{method:'POST',headers:{'Content-Type':'application/json',apikey:EVAL1_CONFIG.publishableKey,...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify({action,...payload}),signal:controller.signal});const data=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(data.error||'Le service est momentanément indisponible.');error.status=response.status;throw error}return data}
 catch(error){if(error.name==='AbortError')throw new Error('La connexion prend trop de temps. Réessaie.');if(error instanceof TypeError)throw new Error('Connexion au serveur impossible. Vérifie Internet et réessaie.');throw error}
 finally{clearTimeout(timeout)}
}
function readAttempt(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return null;const a=JSON.parse(raw);if(a.version!==2||!a.identity||!a.studentToken||!a.id||typeof a.deadline!=='number'||typeof a.startedAt!=='number'||a.deadline-a.startedAt!==DURATION||!['active','submitted'].includes(a.status))return null;return a}catch{storageAvailable=false;return null}}
function persistOnly(){if(!attempt)return;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(attempt));storageAvailable=true}catch{storageAvailable=false}}
function refreshSaveLabel(){const el=$('#save-label');if(!el)return;const pending=ackRevision<(attempt?.revision??0);el.textContent=!storageAvailable?'Sauvegarde locale indisponible : garde la page ouverte':pending?'Envoi au professeur en cours…':'Réponses enregistrées sur le serveur';el.classList.toggle('failed',pending)}
function saveAttempt(){if(!attempt)return;const snapshot=stable(attempt.answers);if(snapshot!==lastSnapshot&&attempt.status==='active'){attempt.revision=(attempt.revision||0)+1;lastSnapshot=snapshot;clearTimeout(saveTimer);saveTimer=setTimeout(()=>syncNow().catch(()=>{}),650)}persistOnly();refreshSaveLabel()}
async function syncNow(submit=false){
 if(!attempt?.studentToken)return;wantsSubmit=wantsSubmit||submit||attempt.status==='submitted';clearTimeout(saveTimer);
 if(syncPromise){await syncPromise.catch(()=>{});if(ackRevision<attempt.revision||wantsSubmit&&attempt.delivery!=='received')return syncNow(wantsSubmit);return}
 if(ackRevision>=attempt.revision&&!wantsSubmit)return;
 const owner=attempt;const revision=owner.revision;const answers={...owner.answers};const isFinal=wantsSubmit;
 syncPromise=(async()=>{
  try{
   const received=await api('save',{id:owner.id,revision,answers,submit:isFinal},owner.studentToken);
   if(attempt!==owner)return;
   owner.serverOffset=Date.parse(received.serverNow)-Date.now();ackRevision=Math.max(ackRevision,received.revision);owner.lastSavedAt=received.lastSavedAt;
   if(received.status==='submitted'){
    owner.status='submitted';owner.reason=received.reason;owner.submittedAt=Date.parse(received.submittedAt);owner.durationSeconds=Math.min(1200,Math.round((owner.submittedAt-owner.startedAt)/1000));clearInterval(timerHandle);
    owner.serverReceipt=true;owner.delivery=stable(received.answers)===stable(owner.answers)?'received':'incomplete';owner.serverAnswers=received.answers;owner.serverSubmittedAt=received.submittedAt;wantsSubmit=false;
    $$('dialog[open]').forEach(closeDialog);renderResult();
   }else if(received.stale){owner.answers=received.answers;owner.revision=received.revision;lastSnapshot=stable(owner.answers);persistOnly();renderExam();showNotice('Une version plus récente a été reçue du serveur. Une seule fenêtre doit être utilisée pour cette copie.')}
   persistOnly();refreshSaveLabel();
  }catch(error){if(attempt===owner){owner.delivery=owner.status==='submitted'?'pending':owner.delivery;owner.networkError=error.message;persistOnly();const el=$('#save-label');if(el){el.textContent='Connexion interrompue : réponses gardées sur cet appareil';el.classList.add('failed')}if(owner.status==='submitted')renderResult()}throw error}
 })();
 try{await syncPromise}finally{syncPromise=null}
 if(attempt===owner&&owner.status==='active'&&ackRevision<owner.revision)return syncNow();
}
async function startAttempt(e){
 e.preventDefault();const name=$('#student-name').value.normalize('NFKC').trim().replace(/\s+/g,' ');$('#name-error').hidden=true;$('#identity-error').hidden=true;$('#student-name').removeAttribute('aria-invalid');
 if(name.length<3||name.split(' ').length<2||!/[\p{L}]/u.test(name)){$('#name-error').textContent='Écris ton prénom et ton nom complets.';$('#name-error').hidden=false;$('#student-name').setAttribute('aria-invalid','true');$('#student-name').focus();return}
 if(!identityChoices.identity_class||!identityChoices.identity_group){$('#identity-error').textContent='Choisis ta classe et ton groupe.';$('#identity-error').hidden=false;return}
 const button=$('.start-button');button.disabled=true;button.textContent='Connexion au serveur…';
 const identity={name,className:identityChoices.identity_class,group:identityChoices.identity_group};
 try{
 let pending;try{pending=JSON.parse(localStorage.getItem(STORAGE_KEY+'.start')||'null')}catch{}
 if(!pending||JSON.stringify(pending.identity)!==JSON.stringify(identity)){const bytes=crypto.getRandomValues(new Uint8Array(32));pending={identity,requestKey:crypto.randomUUID?.()||requestUUID(),studentToken:'e1s_'+[...bytes].map(x=>x.toString(16).padStart(2,'0')).join('')};try{localStorage.setItem(STORAGE_KEY+'.start',JSON.stringify(pending))}catch{}}
  const response=await api('start',pending);serverOffset=Date.parse(response.serverNow)-Date.now();
  attempt={version:2,id:response.id,studentToken:pending.studentToken,identity,startedAt:Date.parse(response.startedAt),deadline:Date.parse(response.deadline),serverOffset,revision:response.revision,answers:response.answers,status:response.status,section:0,submittedAt:response.submittedAt?Date.parse(response.submittedAt):null,reason:response.reason,delivery:response.status==='submitted'?'received':null};
  lastSnapshot=stable(attempt.answers);ackRevision=attempt.revision;wantsSubmit=false;hasWarned=false;closeCombos();persistOnly();try{localStorage.removeItem(STORAGE_KEY+'.start')}catch{}
  attempt.status==='submitted'?renderResult():renderExam();
 }catch(error){$('#identity-error').textContent=error.message;$('#identity-error').hidden=false;button.disabled=false;button.innerHTML=tx('Commencer mes 20 minutes')+' '+icon('arrow')}
}
async function resumeRemote(){const button=$('#resume-attempt');if(button){button.disabled=true;button.textContent='Reprise de la session…'}
 try{const response=await api('status',{id:attempt.id},attempt.studentToken);attempt.serverOffset=Date.parse(response.serverNow)-Date.now();ackRevision=response.revision;
  if(response.status==='submitted'){const unsent=attempt.revision>response.revision&&stable(attempt.answers)!==stable(response.answers);if(!unsent)attempt.answers=response.answers;attempt.serverAnswers=response.answers;attempt.status='submitted';attempt.reason=response.reason;attempt.submittedAt=Date.parse(response.submittedAt);attempt.delivery=unsent?'incomplete':'received';attempt.serverReceipt=true;attempt.durationSeconds=Math.min(1200,Math.round((attempt.submittedAt-attempt.startedAt)/1000));attempt.revision=response.revision}
  else if(response.revision>=attempt.revision){attempt.answers=response.answers;attempt.revision=response.revision}
  lastSnapshot=stable(attempt.answers);persistOnly();attempt.status==='submitted'?renderResult():renderExam();if(attempt.status==='active'&&attempt.revision>ackRevision)syncNow().catch(()=>{});
 }catch(error){if(button){button.disabled=false;button.textContent='Réessayer la reprise'}showNotice(error.message)}
}
function renderLogin(){renderLoginOriginal();lastSnapshot=stable(attempt?.answers??{});const help=$('.login-help>div');if(help)help.innerHTML=tx('Survole une phrase pour afficher sa traduction arabe complète.')+'<br>'+tx('Déplace la souris pour masquer l’infobulle.');const footer=$('.login-footer');if(footer)footer.insertAdjacentHTML('beforeend','<a class="teacher-link" href="enseignant/">Espace professeur →</a>');const example=$('.hover-example');if(example)example.remove();}
function qcard(id,n,title,points,body){const value=QUESTION_MAX[id]??points;return `<article class="question-card" id="${id}" data-question="${id}"><div class="question-top"><span class="question-number">${DISPLAY_NUMBER[id]??String(n).padStart(2,'0')}</span><h2>${tx(title)}</h2><span class="points">${String(value).replace('.',',')} ${value===1?'point':'points'}</span></div>${body}</article>`}
function internalExercise(){return qcard('q6b','6B','Reconnais les éléments de l’unité centrale.',4,`<p class="question-hint">${tx('Observe les huit photos et choisis le nom de chaque composant. Tu peux agrandir les images.')}</p><div class="internal-grid">${[['cpu','A'],['ram','B'],['motherboard','C'],['disks','D'],['power','E'],['gpu','F'],['sound','G'],['wifi','H']].map(([image,letter])=>`<div class="internal-card"><div class="internal-photo ${image==='disks'?'dual':''}"><span class="material-letter">${letter}</span>${image==='disks'?`<img src="${ASSETS.disk}" alt="Premier disque à identifier"><img src="${ASSETS.ssd}" alt="Second disque à identifier">`:`<img src="${ASSETS[image]}" alt="Composant ${letter} à identifier">`}<button class="zoom-button" data-zoom="${image==='disks'?'disk':image}" data-letter="${letter}" type="button" aria-label="Agrandir le composant ${letter}">${icon('zoom')}</button></div><div class="internal-fields"><span class="field-label">${tx('Nom du composant')}</span>${combo('internal_'+image,INTERNAL_OPTIONS,'Nom du composant '+letter)}</div></div>`).join('')}</div>`)}
function sectionContent(n){
 if(n===0){const old=sectionContentOriginal(0);const tail=old.slice(old.indexOf('<article class="question-card" id="q3"'));
  return qcard('q1',1,'Complète la définition de l’informatique.',1,`<p class="question-hint">${tx('Choisis un mot dans chaque liste.')}</p><div class="cloze">${tx('L’informatique est la science du traitement')} ${combo('definition_automatic',['automatique','manuel','matériel','informatique'],'Premier mot de la définition')} ${tx('des')} ${combo('definition_information',['informations','périphériques','ordinateurs','câbles'],'Deuxième mot de la définition')}.</div>`)+qcard('q2',2,'Quelle est la forme de l’information décrite sous chaque image ?',1,`<p class="question-hint">${tx('Lis la légende : on classe l’information décrite, pas la photographie qui l’illustre.')}</p><div class="form-examples">${[['form-sms','Un SMS écrit sur l’écran du téléphone.','form_sms'],['form-photo','Une photographie d’un arbre.','form_photo'],['form-ring','La sonnerie que tu entends.','form_ring'],['form-video','Un clip filmé avec cette caméra.','form_video']].map(([image,label,id])=>`<div class="form-example"><div class="form-photo"><img src="${ASSETS[image]}" alt="Illustration de l’exemple">${image==='form-ring'?`<button class="audio-demo" id="play-ring" type="button">${tx('Écouter la sonnerie')}</button>`:''}</div><div class="form-example-content"><p class="form-caption">${tx(label)}</p>${combo(id,FORM_OPTIONS,label)}</div></div>`).join('')}</div>`)+tail;
 }
 let result=sectionContentOriginal(n);
 if(n===1)return result.replace(tx('Tu peux agrandir les photos. Chaque nom et chaque catégorie valent 0,5 point.'),tx('Tu peux agrandir les photos. Nom : 0,25 point ; catégorie : 0,5 point.'));
 if(n===2){const index=result.indexOf('<article class="question-card" id="q7"');return result.slice(0,index)+internalExercise()+result.slice(index)}
 const situation=tx('Le club prépare un reportage. Il veut enregistrer une voix, conserver le fichier après l’arrêt du PC, puis copier une vidéo de 2 500 Mo sur une clé USB qui dispose de 3 Go libres.').replace('2 500 Mo','<b class="data-inline">2 500 Mo</b>').replace('3 Go','<b class="data-inline">3 Go</b>');
 result=result.replace(/(<div class="situation">[\s\S]*?<p>)[\s\S]*?<\/p>/,'$1'+situation+'</p>');
 const replacement=qcard('q9',9,'Quel composant interne faut-il choisir pour garder le fichier après l’arrêt du PC ?',2,`<p class="question-hint">${tx('Choisis le composant, puis la justification de ton choix.')}</p><div class="choice-reason"><div><label>${tx('Composant choisi')}</label>${combo('storage_choice',['Le disque SSD','La mémoire RAM','Le processeur','L’alimentation'],'Composant choisi pour conserver le fichier')}</div><div><label>${tx('Justification du choix')}</label>${combo('storage_reason',['Il conserve les fichiers même quand le PC est éteint.','Il affiche les images sur l’écran.','Il fournit le courant électrique aux composants.','Il saisit la voix dans l’ordinateur.'],'Justification du choix de stockage')}</div></div>`);
 return result.replace(/<article class="question-card" id="q9"[\s\S]*?<\/article>/,replacement);
}
function updateProgress(){if(!attempt)return;const n=completedCount();const p=$('#progress-text');if(p)p.textContent=`${n} / ${TOTAL_QUESTIONS} exercices complétés`;const bar=$('.progress-track');if(bar){bar.setAttribute('aria-valuemax',String(TOTAL_QUESTIONS));bar.setAttribute('aria-valuenow',String(n))}const fill=$('#progress-fill');if(fill)fill.style.width=`${n/TOTAL_QUESTIONS*100}%`;SECTIONS.forEach((s,i)=>{const done=s.questions.every(complete);const b=$(`[data-section="${i}"]`);if(b)b.classList.toggle('complete',done);const num=$(`[data-part-number="${i}"]`);if(num)num.innerHTML=done?icon('check'):String(i+1)})}
function renderExam(){renderExamOriginal();const total=$('.progress-card>.muted');if(total)total.textContent=TOTAL_QUESTIONS+' exercices au total';refreshSaveLabel()}
function review(){if(!attempt||attempt.status!=='active')return;tick();if(attempt.status!=='active')return;const n=completedCount();$('#review-info').textContent=n===TOTAL_QUESTIONS?'Tous les exercices sont complétés. Prends un instant pour relire avant de rendre.':`${TOTAL_QUESTIONS-n} exercice(s) ne sont pas encore entièrement complétés. Tu peux y revenir ou rendre ta copie en l’état.`;$('#review-count').textContent=`${n} / ${TOTAL_QUESTIONS}`;$('#review-list').innerHTML=Object.keys(GROUPS).map(q=>`<button type="button" class="review-item ${complete(q)?'':'todo'}" data-review-question="${q}">${icon(complete(q)?'check':'paper')}<span>${DISPLAY_NUMBER[q]}. ${esc(QUESTION_TITLES[q])}</span></button>`).join('');openDialog($('#review-dialog'))}
function tick(){if(!attempt||attempt.status!=='active')return;const left=attempt.deadline-clockNow();const v=$('#time-value');if(v)v.textContent=formatTime(left);const t=$('#exam-timer');if(t){t.classList.toggle('warning',left<=120000&&left>60000);t.classList.toggle('urgent',left<=60000);t.setAttribute('aria-label',`Temps restant ${formatTime(left)}`)}if(left<=120000&&left>0&&!hasWarned){hasWarned=true;showNotice('Il reste moins de 2 minutes. Pense à relire tes réponses.')}if(left<=0)submitAttempt('timeout')}
function submitAttempt(reason){if(!attempt||attempt.status!=='active')return;const now=clockNow();if(now>=attempt.deadline)reason='timeout';attempt.status='submitted';attempt.reason=reason;attempt.submittedAt=reason==='timeout'?attempt.deadline:now;attempt.durationSeconds=Math.min(1200,Math.max(0,Math.round((attempt.submittedAt-attempt.startedAt)/1000)));attempt.revision++;attempt.delivery='pending';clearInterval(timerHandle);clearTimeout(noticeHandle);$('#time-notice').hidden=true;$$('dialog[open]').forEach(closeDialog);closeCombos();hideTooltip();persistOnly();renderResult();window.scrollTo(0,0);syncNow(true).catch(()=>{})}
function renderResult(){renderResultOriginal();const view=$('#result-view');if(!view)return;const text=attempt.delivery==='received'?'Copie reçue par le professeur.':attempt.delivery==='incomplete'?'Le serveur a clôturé l’évaluation à la fin des 20 minutes. La dernière version reçue avant la limite est enregistrée ; certaines réponses locales n’ont pas pu être prises en compte.':'Envoi de la copie en cours. Garde cette page ouverte jusqu’à confirmation.';const actions=$('.delivery-anchor');actions.insertAdjacentHTML('beforebegin',`<div class="delivery-box ${attempt.delivery==='received'?'':attempt.delivery==='incomplete'?'error':'pending'}" role="status">${esc(text)}${attempt.delivery==='pending'?'<br><button type="button" class="button-soft" id="retry-send">Réessayer l’envoi</button>':''}${attempt.networkError&&attempt.delivery==='pending'?'<br>'+esc(attempt.networkError):''}</div>`);actions.remove();const metrics=$$('.result-metrics strong');if(metrics[0])metrics[0].textContent=`${completedCount()} / ${TOTAL_QUESTIONS}`;const status=$('.result-status');if(status)status.textContent=attempt.delivery==='received'?'Copie reçue':attempt.delivery==='incomplete'?'Copie clôturée':'Envoi en attente';const next=$('#new-student');if(next)next.disabled=attempt.delivery==='pending';}
function summaryBody(){return Object.keys(GROUPS).map(q=>`<div class="copy-question"><h3>${DISPLAY_NUMBER[q]}. ${esc(QUESTION_TITLES[q])}</h3>${GROUPS[q].map(id=>`<div class="copy-line"><span>${esc(LABELS[id])} :</span> ${answered(id)?`<b>${esc(attempt.answers[id])}</b>`:'<b class="unanswered">Sans réponse</b>'}</div>`).join('')}</div>`).join('')}
document.addEventListener('click',e=>{if(e.target.closest('#resume-attempt')){e.preventDefault();e.stopImmediatePropagation();resumeRemote();return}if(e.target.closest('#retry-send')){e.preventDefault();e.stopImmediatePropagation();syncNow(true).catch(()=>{});return}if(e.target.closest('#play-ring')){e.preventDefault();e.stopImmediatePropagation();const Audio=window.AudioContext||window.webkitAudioContext;if(Audio){const audio=new Audio();for(let i=0;i<4;i++){const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=i%2?880:660;gain.gain.value=.09;osc.connect(gain);gain.connect(audio.destination);osc.start(audio.currentTime+i*.35);osc.stop(audio.currentTime+i*.35+.2)}setTimeout(()=>audio.close(),1900)}return}},true);
window.addEventListener('online',()=>{if(attempt?.studentToken&&(attempt.status==='active'||attempt.delivery==='pending'))syncNow(attempt.status==='submitted').catch(()=>{})});
window.addEventListener('pagehide',()=>persistOnly());

