attempt=readAttempt();
if(attempt){lastSnapshot=stable(attempt.answers);ackRevision=attempt.serverReceipt?attempt.revision:-1;if(attempt.status==='submitted'){renderResult();if(attempt.delivery==='pending')syncNow(true).catch(()=>{})}else renderLogin()}else renderLogin();
